SELECT cm.cost_id, cm.cost_no, cm.cycle_id, cc.cycle_code, cc.cycle_name,
       cm.dept_id, d.dept_code, d.dept_name,
       cm.element_type, cm.cost_amount, cm.occur_date, cm.pay_type, cm.remark,
       cm.create_user, cm.create_time, cm.update_time
FROM cost_main cm
LEFT JOIN cost_cycle cc ON cm.cycle_id = cc.cycle_id
LEFT JOIN sys_dept d ON cm.dept_id = d.dept_id

    
        AND cm.cycle_id = #{cycleId}
    
    
        AND cm.dept_id = #{deptId}
    
    
        AND cm.element_type = #{elementType}
    
    
        AND DATE(cm.occur_date) >= #{startDate}
    
    
        AND DATE(cm.occur_date) <= #{endDate}
    

ORDER BY cm.create_time DESC

SELECT cm.cost_id, cm.cost_no, cm.cycle_id, cc.cycle_code, cc.cycle_name, cm.dept_id, d.dept_code, d.dept_name, cm.element_type, cm.cost_amount, cm.occur_date, cm.pay_type, cm.remark, cm.create_user, cm.create_time, cm.update_time FROM cost_main cm LEFT JOIN cost_cycle cc ON cm.cycle_id = cc.cycle_id LEFT JOIN sys_dept d ON cm.dept_id = d.dept_id WHERE cm.dept_id = #{deptId}
AND cm.cycle_id = #{cycleId}
AND cm.element_type = #{elementType}
ORDER BY cm.create_time DESC

SELECT COUNT(1)
FROM cost_main cm

    
        AND cm.cycle_id = #{cycleId}
    
    
        AND cm.dept_id = #{deptId}
    
    
        AND cm.element_type = #{elementType}
    
    
        AND DATE(cm.occur_date) >= #{startDate}
    
    
        AND DATE(cm.occur_date) <= #{endDate}

SELECT COUNT(1)
FROM cost_main cm
WHERE cm.dept_id = #{deptId}

    AND cm.cycle_id = #{cycleId}
